args<-commandArgs(trailingOnly=TRUE);Sys.setenv(PHASE1RR_ROOT=normalizePath(args[1]));source(file.path(Sys.getenv('PHASE1RR_ROOT'),'10_code/phase1rr_common.R'));cid<-'mTKO_B16_T17';tr<-readRDS(file.path(O,paste0(cid,'.TRAIN.rds')));sp<-readRDS(file.path(O,paste0(cid,'.SPIKE.rds')));meta<-fread(file.path(Q,paste0(cid,'.PRESPECIFIED_SPIKE_GENES.tsv')));idx<-match(meta$gene,tr$gene);rows<-list()
for(b in 1:60){p<-(1+rowSums(abs(tr$score)>=abs(sp$score[,b])))/1001;q<-p.adjust(p,'BH');z<-copy(meta);z[,empirical_P:=p[idx]];z[,empirical_FDR:=q[idx]];z[,estimated_log2FC:=sp$effect[idx,b]];z[,simulation:=b];rows[[b]]<-z}
a<-rbindlist(rows);write_tsv(a,file.path(Q,'SPIKE_GENE_RECOVERY.tsv.gz'));a[,abs_effect:=abs(true_log2FC)];summ<-a[,.(n_unique_genes=uniqueN(gene),n_simulations=uniqueN(simulation),power_P05=mean(empirical_P<=.05),power_BH10=mean(empirical_FDR<=.10),sign_accuracy=mean(estimated_log2FC*true_log2FC>0),mean_effect_bias=mean(estimated_log2FC-true_log2FC),median_abs_effect_bias=median(abs(estimated_log2FC-true_log2FC))),by=.(abs_effect,ab_stratum,guide_stratum)];write_tsv(summ,file.path(Q,'SPIKE_STRATUM_RECOVERY.tsv'));cat('Spike stratum diagnostics written\n')
